import itertools

def count_paths(grid):
    N = len(grid)
    P = [[0]*N for _ in range(N)]

    # We need to compute P in increasing order of grid values
    # or just use recursion with memoization.
    memo = {}
    def get_P(r, c):
        if (r, c) in memo:
            return memo[(r, c)]

        res = 1
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                if grid[nr][nc] > grid[r][c]:
                    res += get_P(nr, nc)
        memo[(r, c)] = res
        return res

    total_paths = 0
    for r in range(N):
        for c in range(N):
            is_min = True
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if grid[nr][nc] < grid[r][c]:
                        is_min = False
                        break
            if is_min:
                total_paths += get_P(r, c)
    return total_paths

