def count_good_paths(board):
    rows = len(board)
    cols = len(board[0])
    n = rows * cols

    # Find local minima
    local_minima = []
    for r in range(rows):
        for c in range(cols):
            is_min = True
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if board[nr][nc] < board[r][c]:
                        is_min = False
                        break
            if is_min:
                local_minima.append((r, c))

    # dp[r][c] is the number of increasing paths starting at (r, c)
    # We need to compute this in descending order of values
    dp = [[0] * cols for _ in range(rows)]
    cells = []
    for r in range(rows):
        for c in range(cols):
            cells.append((board[r][c], r, c))
    cells.sort(key=lambda x: x[0], reverse=True)

    for val, r, c in cells:
        count = 1
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if board[nr][nc] > val:
                    count += dp[nr][nc]
        dp[r][c] = count

    total_paths = 0
    for r, c in local_minima:
        total_paths += dp[r][c]
    return total_paths

