import itertools

def count_good_paths(grid):
    rows = len(grid)
    cols = len(grid[0])
    n = rows * cols

    # Build the graph G
    adj = {}
    for r in range(rows):
        for c in range(cols):
            adj[(r, c)] = []
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] > grid[r][c]:
                        adj[(r, c)].append((nr, nc))

    # A source is a vertex with no incoming edges in G.
    # In our construction, u -> v exists if u and v are adjacent and u < v.
    # So a source is a vertex such that all its neighbors are larger than it.
    sources = []
    for r in range(rows):
        for c in range(cols):
            is_source = True
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] < grid[r][c]:
                        is_source = False
                        break
            if is_source:
                sources.append((r, c))

    # Number of paths starting at v
    f = {}
    # To compute f, we can use memoization or compute in reverse order of values
    # Let's just use recursion with memoization
    def get_f(pos):
        if pos in f:
            return f[pos]
        res = 1
        for neighbor in adj[pos]:
            res += get_f(neighbor)
        f[pos] = res
        return res

    total_paths = 0
    for s in sources:
        total_paths += get_f(s)
    return total_paths

